/**
 * Archive l'instantané des inscriptions d'un événement (snapshot JSON dans
 * event_archives, téléchargeable en CSV depuis l'onglet Archives de l'admin),
 * puis supprime l'événement. DELETE FROM events déclenche ON DELETE CASCADE
 * sur registrations — sans cet archivage préalable, les données de présence/
 * paiement disparaîtraient définitivement avec l'événement.
 * Utilisée à la fois par la suppression manuelle (admin) et par le cron
 * purgeExpiredEvents() ci-dessous.
 * @returns {Promise<{archived_registrations: number}|null>} null si l'événement n'existe pas.
 */
async function archiveAndDeleteEvent(db, eventId) {
  const eventRow = await db.prepare(`SELECT * FROM events WHERE id = ?`).bind(eventId).first();
  if (!eventRow) return null;

  const { results: regsToArchive } = await db.prepare(
    `SELECT * FROM registrations WHERE event_id = ? ORDER BY created_at ASC`
  ).bind(eventId).all();

  await db.prepare(`
    INSERT INTO event_archives (event_id, title, type, date_start, date_end, lieu, registrations_count, registrations_json)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(
    eventRow.id, eventRow.title, eventRow.type, eventRow.date_start, eventRow.date_end, eventRow.lieu,
    regsToArchive.length, JSON.stringify(regsToArchive),
  ).run();

  await db.prepare(`DELETE FROM events WHERE id = ?`).bind(eventId).run();
  return { archived_registrations: regsToArchive.length };
}

// ── Suppression + archivage automatiques des événements expirés (cron J+5) ──
// Activé via [triggers] crons dans wrangler.toml (cron quotidien). Chaque
// événement dont la date de fin (ou de début si pas de date_end) est passée
// depuis plus de 5 jours est automatiquement archivé (cf. archiveAndDeleteEvent
// ci-dessus — instantané JSON des inscriptions conservé dans event_archives,
// téléchargeable en CSV depuis l'onglet Archives de l'admin) puis retiré du
// calendrier. Aucune donnée d'inscription/paiement n'est perdue : seul
// l'événement disparaît de la liste active.
async function purgeExpiredEvents(env) {
  const { results: expired } = await env.DB.prepare(`
    SELECT id FROM events
    WHERE (
      CASE
        WHEN date_end IS NOT NULL AND date_end != ''
          THEN date_end
        ELSE date_start
      END
    ) < date('now', '-5 days')
  `).all();

  let archivedEvents = 0;
  let archivedRegistrations = 0;
  for (const { id } of expired) {
    const result = await archiveAndDeleteEvent(env.DB, id);
    if (result) {
      archivedEvents += 1;
      archivedRegistrations += result.archived_registrations;
    }
  }
  console.log(`[cron] purgeExpiredEvents: ${archivedEvents} événement(s) archivé(s) puis supprimé(s), ${archivedRegistrations} inscription(s) archivée(s)`);
}

// Une inscription "en_attente" liée à un checkout HelloAsso (helloasso_ref
// renseigné) et vieille de plus de 2h est considérée comme un paiement
// potentiellement abandonné : l'utilisateur a quitté HelloAsso sans payer,
// ou n'est jamais revenu (callback /api/checkout/callback jamais atteint —
// fermeture du navigateur, coupure réseau, etc.). Avant d'annuler quoi que
// ce soit, on revérifie chaque cas auprès de l'API HelloAsso : un callback
// manqué ne veut pas dire un paiement manqué, et annuler une inscription
// réellement payée reviendrait à encaisser le paiement d'un adhérent tout
// en libérant sa place à quelqu'un d'autre. Si HelloAsso confirme le
// paiement, on rattrape l'inscription en "paye" (et on envoie l'email de
// confirmation resté bloqué) plutôt que de l'annuler.
async function purgeAbandonedCheckouts(env) {
  const { results } = await env.DB.prepare(`
    SELECT * FROM registrations
    WHERE paiement_status = 'en_attente'
      AND helloasso_ref IS NOT NULL
      AND created_at < datetime('now', '-2 hours')
  `).all();
  if (!results || results.length === 0) return;

  const eventIds = new Set();
  let cancelled = 0;
  let recovered = 0;
  for (const reg of results) {
    let paid = false;
    try {
      const intent = await getHelloAssoCheckoutIntent(env, reg.helloasso_ref);
      paid = buildHelloAssoPaymentState(intent, reg.montant).paid;
    } catch (verifyError) {
      // Vérification impossible (HelloAsso indisponible, etc.) : par
      // prudence on NE marque PAS "annule" ce passage — on retentera au
      // prochain cron plutôt que de risquer d'annuler un paiement réel.
      console.error(`[cron] purgeAbandonedCheckouts: vérification HelloAsso échouée pour #${reg.id}`, verifyError);
      continue;
    }

    if (paid) {
      await env.DB.prepare(`UPDATE registrations SET paiement_status = 'paye' WHERE id = ?`).bind(reg.id).run();
      recovered++;
      try {
        const rawEvent = await env.DB.prepare(`SELECT * FROM events WHERE id = ?`).bind(reg.event_id).first();
        const ev = rawEvent ? await hydrateEvent(env.DB, rawEvent) : null;
        if (ev) await sendConfirmationEmails(env, { reg: { ...reg, paiement_status: 'paye' }, ev, cancelToken: reg.cancel_token });
      } catch (emailError) {
        console.error(`[cron] purgeAbandonedCheckouts: email de confirmation rattrapée échoué pour #${reg.id}`, emailError);
      }
    } else {
      await env.DB.prepare(`UPDATE registrations SET paiement_status = 'annule' WHERE id = ?`).bind(reg.id).run();
      cancelled++;
    }
    eventIds.add(reg.event_id);
  }
  for (const eventId of eventIds) {
    await syncEventAvailability(env.DB, eventId);
  }
  console.log(`[cron] purgeAbandonedCheckouts: ${cancelled} annulée(s), ${recovered} rattrapée(s) comme payée(s) sur ${results.length} vérifiée(s)`);
}

export default {
  // ── Cron trigger quotidien (cf. [triggers] crons dans wrangler.toml) ──
  async scheduled(_event, env, _ctx) {
    await purgeExpiredEvents(env);
    await purgeAbandonedCheckouts(env);
    await sendEventReminders(env);
    await expireWaitlistNotifications(env);
  },

  async fetch(request, env) {
    const url    = new URL(request.url);
    const path   = url.pathname;
    const method = request.method.toUpperCase();

    if ((method === 'GET' || method === 'HEAD') && path === '/api/health') {
      return new Response(JSON.stringify({ ok: true, data: { service: 'calendrier-americanfullfightingbons', date: new Date().toISOString() } }), {
        headers: securityHeaders({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }),
      });
    }

    if ((method === 'GET' || method === 'HEAD') && path === '/api/version') {
      return new Response(JSON.stringify({ ok: true, data: { service: 'calendrier-americanfullfightingbons', version: '1.0.0' } }), {
        headers: securityHeaders({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }),
      });
    }

    if ((method === 'GET' || method === 'HEAD') && path === '/robots.txt') {
      return new Response('User-agent: *\nAllow: /\n\nSitemap: https://calendrier.americanfullfightingbons.fr/sitemap.xml\n', {
        headers: securityHeaders({ 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'public, max-age=3600' }),
      });
    }

    if ((method === 'GET' || method === 'HEAD') && path === '/sitemap.xml') {
      return new Response('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n  <url>\n    <loc>https://calendrier.americanfullfightingbons.fr/</loc>\n    <changefreq>weekly</changefreq>\n    <priority>0.8</priority>\n  </url>\n</urlset>\n', {
        headers: securityHeaders({ 'Content-Type': 'application/xml; charset=utf-8', 'Cache-Control': 'public, max-age=3600' }),
      });
    }

    // ── Logo servi directement par le Worker ──────────────────
    // Remplace l'ancien hot-link vers raw.githubusercontent.com/.../Logo.jpg (2,6 Mo,
    // dépendance non garantie en prod) par une version compressée (~24 Ko, WebP),
    // servie depuis le même domaine que le site avec un cache long (le contenu est figé).
    if ((method === 'GET' || method === 'HEAD') && path === '/logo.webp') {
      const bytes = Uint8Array.from(atob(LOGO_WEBP_BASE64), (c) => c.charCodeAt(0));
      return new Response(bytes, {
        headers: securityHeaders({
          'Content-Type': 'image/webp',
          'Cache-Control': 'public, max-age=31536000, immutable',
        }),
      });
    }

    // ── Affiches d'événements servies depuis R2 ────────────────
    // Route publique (pas d'auth : ce sont des visuels du calendrier public).
    // Cache navigateur long car la clé change à chaque remplacement d'affiche
    // (horodatage dans le nom), donc jamais de contenu périmé servi.
    if ((method === 'GET' || method === 'HEAD') && path.startsWith('/posters/')) {
      const key = decodeURIComponent(path.slice('/posters/'.length));
      if (!key || key.includes('/') || key.includes('..')) {
        return new Response('Not found', { status: 404 });
      }
      const object = await env.POSTERS.get(key);
      if (!object) {
        return new Response('Not found', { status: 404 });
      }
      return new Response(method === 'HEAD' ? null : object.body, {
        headers: securityHeaders({
          'Content-Type': object.httpMetadata?.contentType || 'application/octet-stream',
          'Cache-Control': 'public, max-age=31536000, immutable',
          'Content-Length': String(object.size),
        }),
      });
    }

    // ── Servir index.html embarqué dans le Worker ─────────────
    if ((method === 'GET' || method === 'HEAD') && (path === '/' || path === '' || path === '/index.html')) {
      return new Response(INDEX_HTML, {
        status: 200,
        headers: securityHeaders({
          'Content-Type': 'text/html; charset=utf-8',
          'Cache-Control': 'public, max-age=300',
        }),
      });
    }

    if ((method === 'GET' || method === 'HEAD') && path === '/mentions-legales') {
      return new Response(MENTIONS_HTML, {
        status: 200,
        headers: securityHeaders({
          'Content-Type': 'text/html; charset=utf-8',
          'Cache-Control': 'public, max-age=300',
        }),
      });
    }

    // Page autonome liée depuis l'email de confirmation (cf. sendConfirmationEmails
    // → cancelUrl) — ne réutilise pas la SPA principale pour rester indépendante
    // d'éventuels changements de routing côté index.html.
    if ((method === 'GET' || method === 'HEAD') && /^\/annulation\/[a-zA-Z0-9-]+$/.test(path)) {
      return new Response(ANNULATION_HTML, {
        status: 200,
        headers: securityHeaders({
          'Content-Type': 'text/html; charset=utf-8',
          'Cache-Control': 'no-store',
        }),
      });
    }

    // ── CORS ───────────────────────────────────────────────────
    const corsHeaders = buildCorsHeaders(request, env, url);
    if (method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: securityHeaders(corsHeaders) });
    }

    // ── Helpers internes ───────────────────────────────────────
    const json = (data, status = 200) =>
      new Response(JSON.stringify(data), {
        status,
        headers: securityHeaders({ ...corsHeaders, 'Content-Type': 'application/json' }),
      });

    const err = (msg, status = 400) => json({ error: msg }, status);

    const hasAdminSession = async () => {
      const token = parseCookies(request)[ADMIN_SESSION_COOKIE];
      if (!token) return false;
      const session = await parseSessionToken(token, env);
      return !!session && Number(session.expiresAt || 0) > Date.now() && session.role === 'admin';
    };

    const isAdmin = async () => {
      // Seule la session cookie HMAC est acceptée — le Bearer token statique a été supprimé
      // car il ne peut pas expirer et constitue un accès permanent si le token fuite.
      return hasAdminSession();
    };

    const requireAdmin = async () => {
      if (!(await isAdmin())) throw new ApiError('Non autorisé', 401);
    };

    const genId = (prefix = 'evt') => `${prefix}${Date.now().toString(36)}`;

    const segments = path.replace(/^\/api\//, '').split('/');
    const resource = segments[0];
    const resId    = segments[1];
    const subRes   = segments[2];

    try {
      if (resource === 'auth') {
        if (method === 'POST' && resId === 'login') {
          // Rate limiting : le mot de passe admin (ADMIN_TOKEN) est un secret unique
          // partagé par tout le bureau, sans verrouillage de compte possible — sans
          // limite ici, un brute-force est possible (même protection que sur les
          // inscriptions publiques, mais plus stricte vu la sensibilité de la cible).
          const clientIp = request.headers.get('CF-Connecting-IP') || request.headers.get('X-Forwarded-For') || 'unknown';
          if (isRateLimited(`login:${clientIp}`, 5, 5 * 60_000)) {
            return err('Trop de tentatives de connexion. Réessayez dans quelques minutes.', 429);
          }
          const body = await request.json();
          const password = String(body?.password || '').trim();
          if (!password) return err('Mot de passe incorrect', 401);

          // Vérifie d'abord contre le mot de passe stocké en base (modifiable
          // depuis le panneau Réglages). Si aucune ligne n'existe encore
          // (aucun changement effectué depuis l'installation), on retombe
          // sur le secret Cloudflare ADMIN_TOKEN — comportement historique.
          const stored = await loadAdminCredentials(env.DB);
          const passwordOk = stored
            ? await verifyPassword(password, stored.password_salt, stored.password_hash, stored.iterations)
            : secureEquals(password, String(env.ADMIN_TOKEN || '').trim());

          if (!passwordOk) {
            return err('Mot de passe incorrect', 401);
          }
          const token = await createSessionToken(
            { role: 'admin', expiresAt: Date.now() + ADMIN_SESSION_TTL_MS },
            env
          );
          return new Response(JSON.stringify({ ok: true }), {
            status: 200,
            headers: securityHeaders({
              ...corsHeaders,
              'Content-Type': 'application/json',
              'Set-Cookie': buildSessionCookie(token),
            }),
          });
        }

        if (method === 'GET' && resId === 'session') {
          return json({ ok: await isAdmin() });
        }

        if (method === 'POST' && resId === 'logout') {
          return new Response(JSON.stringify({ ok: true }), {
            status: 200,
            headers: securityHeaders({
              ...corsHeaders,
              'Content-Type': 'application/json',
              'Set-Cookie': clearSessionCookie(),
            }),
          });
        }

        if (method === 'PUT' && resId === 'password') {
          await requireAdmin();

          // Même logique de rate limiting que le login : on est déjà admin,
          // mais ça évite qu'une session volée serve à essayer en boucle un
          // "mot de passe actuel" pour deviner l'existant.
          const clientIp = request.headers.get('CF-Connecting-IP') || request.headers.get('X-Forwarded-For') || 'unknown';
          if (isRateLimited(`password-change:${clientIp}`, 5, 5 * 60_000)) {
            return err('Trop de tentatives. Réessayez dans quelques minutes.', 429);
          }

          const body = await request.json();
          const currentPassword = String(body?.currentPassword || '').trim();
          const newPassword = String(body?.newPassword || '').trim();

          if (!currentPassword || !newPassword) {
            return err('Mot de passe actuel et nouveau mot de passe requis');
          }
          if (newPassword.length < 12) {
            return err('Le nouveau mot de passe doit contenir au moins 12 caractères');
          }

          const stored = await loadAdminCredentials(env.DB);
          const currentOk = stored
            ? await verifyPassword(currentPassword, stored.password_salt, stored.password_hash, stored.iterations)
            : secureEquals(currentPassword, String(env.ADMIN_TOKEN || '').trim());

          if (!currentOk) {
            return err('Mot de passe actuel incorrect', 401);
          }

          const { hash, salt, iterations } = await hashPassword(newPassword);
          await saveAdminCredentials(env.DB, { hash, salt, iterations });

          return json({ ok: true });
        }
      }

      // ══════════════════════════════════════════════════════════
      //  EVENTS
      // ══════════════════════════════════════════════════════════
      if (resource === 'events') {

        if (method === 'GET' && !resId) {
          const { results } = await env.DB.prepare(`
            SELECT * FROM events
            ORDER BY
              CASE WHEN date_start >= date('now') THEN 0 ELSE 1 END ASC,
              date_start ASC
          `).all();
          return json(await hydrateEvents(env.DB, results));
        }

        // GET /api/events/:id/ics [public] — export calendrier (RFC 5545),
        // à placer AVANT le GET générique ci-dessous (même resId, subRes en plus).
        if (method === 'GET' && resId && subRes === 'ics') {
          const ev = await env.DB.prepare(`SELECT * FROM events WHERE id = ?`).bind(resId).first();
          if (!ev) return err('Événement introuvable', 404);
          const ics = buildEventIcs(ev);
          const safeFilename = String(ev.title || 'evenement')
            .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
            .replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60) || 'evenement';
          return new Response(ics, {
            headers: securityHeaders({
              ...corsHeaders,
              'Content-Type': 'text/calendar; charset=utf-8',
              'Content-Disposition': `attachment; filename="${safeFilename}.ics"`,
            }),
          });
        }

        // POST /api/events/series [admin] — crée plusieurs occurrences d'un même
        // événement (ex: cours hebdomadaire), à placer AVANT le POST générique
        // ci-dessous (même méthode, resId='series' en plus). Corps attendu :
        // { template: {...mêmes champs que la création d'un événement, sans date_start},
        //   date_start, weekday_interval_days (par défaut 7), occurrences (nombre d'occurrences) }
        if (method === 'POST' && resId === 'series') {
          await requireAdmin();
          const body = await request.json();
          const template = body.template || {};
          const occurrences = Number(body.occurrences);
          const intervalDays = Number(body.interval_days) || 7;
          if (!Number.isInteger(occurrences) || occurrences < 1 || occurrences > 52) {
            return err('occurrences doit être un entier entre 1 et 52');
          }
          if (!body.date_start || !/^\d{4}-\d{2}-\d{2}$/.test(String(body.date_start))) {
            return err('date_start doit être au format YYYY-MM-DD');
          }
          validateEvent({ ...template, date_start: body.date_start });

          const seriesId = `series${Date.now().toString(36)}`;
          const created = [];
          const startDate = new Date(`${body.date_start}T00:00:00Z`);
          for (let i = 0; i < occurrences; i += 1) {
            const occDate = new Date(startDate.getTime() + i * intervalDays * 86_400_000);
            const occDateStr = occDate.toISOString().slice(0, 10);
            const id = genId('evt');
            await env.DB.prepare(`
              INSERT INTO events
                (id, title, sub, type, status, date_start, date_end, time_start, time_end,
                 lieu, price, spots_total, spots_left, featured, is_grade, helloasso, helloasso_url, series_id)
              VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            `).bind(
              id, template.title, template.sub, template.type,
              template.status ?? 'disponible',
              occDateStr, template.date_end ?? null,
              template.time_start ?? null, template.time_end ?? null,
              template.lieu, template.price ?? 0,
              template.spots_total ?? 0, template.spots_total ?? 0,
              template.featured  ? 1 : 0, template.is_grade  ? 1 : 0,
              template.helloasso ? 1 : 0, template.helloasso_url ?? null,
              seriesId,
            ).run();
            created.push(id);
          }
          return json({ series_id: seriesId, created_event_ids: created }, 201);
        }

        // DELETE /api/events/series/:seriesId [admin] — supprime (avec archivage,
        // cf. archiveAndDeleteEvent) toutes les occurrences encore présentes
        // d'une série créée via POST /api/events/series.
        if (method === 'DELETE' && resId === 'series' && subRes) {
          await requireAdmin();
          const { results: seriesEvents } = await env.DB.prepare(
            `SELECT id, poster_key FROM events WHERE series_id = ?`
          ).bind(subRes).all();
          let archivedRegistrations = 0;
          for (const { id, poster_key } of seriesEvents) {
            const result = await archiveAndDeleteEvent(env.DB, id);
            if (result) archivedRegistrations += result.archived_registrations;
            if (poster_key) await deleteEventPosterKey(env, poster_key);
          }
          return json({ deleted_events: seriesEvents.length, archived_registrations: archivedRegistrations });
        }

        if (method === 'GET' && resId) {
          const ev = await env.DB.prepare(
            `SELECT * FROM events WHERE id = ?`
          ).bind(resId).first();
          if (!ev) return err('Événement introuvable', 404);
          return json(await hydrateEvent(env.DB, ev));
        }

        if (method === 'POST') {
          await requireAdmin();
          const body = await request.json();
          const id   = body.id || genId('evt');
          validateEvent(body);
          await env.DB.prepare(`
            INSERT INTO events
              (id, title, sub, type, status, date_start, date_end, time_start, time_end,
               lieu, price, spots_total, spots_left, featured, is_grade, helloasso, helloasso_url)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
          `).bind(
            id, body.title, body.sub, body.type,
            body.status ?? 'disponible',
            body.date_start, body.date_end ?? null,
            body.time_start ?? null, body.time_end ?? null,
            body.lieu, body.price ?? 0,
            body.spots_total ?? 0, body.spots_left ?? body.spots_total ?? 0,
            body.featured  ? 1 : 0, body.is_grade  ? 1 : 0,
            body.helloasso ? 1 : 0, body.helloasso_url ?? null,
          ).run();
          const created = await syncEventAvailability(env.DB, id);
          return json(created, 201);
        }

        if (method === 'PUT' && resId && !subRes) {
          await requireAdmin();
          const body = await request.json();
          validateEvent(body);
          await env.DB.prepare(`
            UPDATE events SET
              title = ?, sub = ?, type = ?, status = ?,
              date_start = ?, date_end = ?, time_start = ?, time_end = ?,
              lieu = ?, price = ?, spots_total = ?, spots_left = ?,
              featured = ?, is_grade = ?, helloasso = ?, helloasso_url = ?
            WHERE id = ?
          `).bind(
            body.title, body.sub, body.type, body.status ?? 'disponible',
            body.date_start, body.date_end ?? null,
            body.time_start ?? null, body.time_end ?? null,
            body.lieu, body.price ?? 0,
            body.spots_total ?? 0, body.spots_left ?? body.spots_total ?? 0,
            body.featured  ? 1 : 0, body.is_grade  ? 1 : 0,
            body.helloasso ? 1 : 0, body.helloasso_url ?? null,
            resId,
          ).run();
          const updated = await syncEventAvailability(env.DB, resId);
          if (!updated) return err('Événement introuvable', 404);
          return json(updated);
        }

        // PUT /api/events/:id/poster [admin] — téléverse/remplace l'affiche.
        // Corps de requête = octets bruts de l'image, Content-Type = mime réel
        // (le client envoie directement le File sélectionné, pas de multipart).
        if (method === 'PUT' && resId && subRes === 'poster') {
          await requireAdmin();
          const existing = await env.DB.prepare('SELECT poster_key FROM events WHERE id = ?').bind(resId).first();
          if (!existing) return err('Événement introuvable', 404);

          const contentType = request.headers.get('Content-Type') || '';
          const arrayBuffer = await request.arrayBuffer();
          const newKey = await uploadEventPoster(env, resId, arrayBuffer, contentType);

          await env.DB.prepare(
            `UPDATE events SET poster_key = ?, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id = ?`
          ).bind(newKey, resId).run();

          // Supprime l'ancienne affiche seulement après succès de l'upload +
          // écriture DB, pour ne jamais perdre l'ancienne image si une étape
          // précédente échoue.
          if (existing.poster_key) await deleteEventPosterKey(env, existing.poster_key);

          return json({ poster_url: `/posters/${newKey}` });
        }

        // DELETE /api/events/:id/poster [admin] — retire l'affiche (sans
        // supprimer l'événement lui-même).
        if (method === 'DELETE' && resId && subRes === 'poster') {
          await requireAdmin();
          const existing = await env.DB.prepare('SELECT poster_key FROM events WHERE id = ?').bind(resId).first();
          if (!existing) return err('Événement introuvable', 404);
          if (existing.poster_key) {
            await deleteEventPosterKey(env, existing.poster_key);
            await env.DB.prepare(
              `UPDATE events SET poster_key = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id = ?`
            ).bind(resId).run();
          }
          return json({ ok: true });
        }

        if (method === 'DELETE' && resId && !subRes) {
          await requireAdmin();
          // Archivage automatique des inscriptions avant suppression (cf.
          // archiveAndDeleteEvent ci-dessus) — même logique que le cron
          // purgeExpiredEvents, déclenchée ici manuellement par l'admin.
          // L'affiche R2 éventuelle est aussi supprimée pour ne pas laisser
          // de fichier orphelin dans le bucket.
          const existing = await env.DB.prepare('SELECT poster_key FROM events WHERE id = ?').bind(resId).first();
          const result = await archiveAndDeleteEvent(env.DB, resId);
          if (!result) return err('Événement introuvable', 404);
          if (existing?.poster_key) await deleteEventPosterKey(env, existing.poster_key);
          return json({ deleted: resId, archived_registrations: result.archived_registrations });
        }
      }

      // ══════════════════════════════════════════════════════════
      //  ARCHIVES — inscriptions des événements supprimés
      // ══════════════════════════════════════════════════════════
      if (resource === 'archives') {
        await requireAdmin();

        // GET /api/archives [admin] — liste des archives (sans le JSON complet)
        if (method === 'GET' && !resId) {
          const { results } = await env.DB.prepare(
            `SELECT id, event_id, title, type, date_start, date_end, lieu, registrations_count, archived_at
             FROM event_archives ORDER BY archived_at DESC`
          ).all();
          return json(results);
        }

        // GET /api/archives/:id/csv [admin] — export CSV de l'archive
        if (method === 'GET' && resId && subRes === 'csv') {
          const archive = await env.DB.prepare(`SELECT * FROM event_archives WHERE id = ?`).bind(resId).first();
          if (!archive) return err('Archive introuvable', 404);
          let regs = [];
          try { regs = JSON.parse(archive.registrations_json) || []; } catch { regs = []; }

          const headers = ['Nom', 'Prénom', 'Date de naissance', 'Téléphone', 'Email', 'Licence FFK', 'Mineur', 'Catégorie', 'Niveau', 'Régime', 'Parent', 'Téléphone parent', 'Message', 'Montant', 'Statut paiement'];
          const csvEscape = (value) => {
            const str = String(value ?? '');
            return /[";\n]/.test(str) ? `"${str.replace(/"/g, '""')}"` : str;
          };
          const rows = regs.map(r => [
            r.nom, r.prenom, r.date_naissance, r.telephone, r.email, r.licence_ffk || '',
            r.is_mineur ? 'Oui' : 'Non', r.categorie || '', r.niveau || '', r.regime || '',
            r.is_mineur ? `${r.parent_prenom || ''} ${r.parent_nom || ''}`.trim() : '',
            r.is_mineur ? (r.parent_tel || '') : '',
            r.message || '', r.montant, r.paiement_status,
          ].map(csvEscape).join(';'));
          const csv = '\uFEFF' + [headers.join(';'), ...rows].join('\n');

          const safeFilename = String(archive.title || 'evenement')
            .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
            .replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60) || 'evenement';
          return new Response(csv, {
            headers: securityHeaders({
              ...corsHeaders,
              'Content-Type': 'text/csv; charset=utf-8',
              'Content-Disposition': `attachment; filename="inscrits_${safeFilename}_${archive.date_start || ''}.csv"`,
            }),
          });
        }

        // DELETE /api/archives/:id [admin] — purge manuelle d'une archive
        // (une fois le CSV téléchargé et sauvegardé ailleurs si besoin)
        if (method === 'DELETE' && resId) {
          const info = await env.DB.prepare(`DELETE FROM event_archives WHERE id = ?`).bind(resId).run();
          if (info.changes === 0) return err('Archive introuvable', 404);
          return json({ deleted: resId });
        }
      }

      // ══════════════════════════════════════════════════════════
      //  REGISTRATIONS
      // ══════════════════════════════════════════════════════════
      if (resource === 'registrations') {

        // GET /api/registrations/public [public]
        if (method === 'GET' && resId === 'public') {
          const { results } = await env.DB.prepare(`
            SELECT e.id AS event_id,
                   e.title AS event_title,
                   e.date_start,
                   COUNT(r.id) AS registrations_count
            FROM events e
            LEFT JOIN registrations r
              ON r.event_id = e.id
             AND r.paiement_status IN ('en_attente', 'paye', 'gratuit')
            WHERE e.date_start >= date('now')
            GROUP BY e.id, e.title, e.date_start
            ORDER BY e.date_start ASC
            LIMIT 20
          `).all();
          return json(results);
        }

        // GET /api/registrations [admin]
        if (method === 'GET' && !resId) {
          await requireAdmin();
          const eventFilter  = url.searchParams.get('event_id');
          const statusFilter = url.searchParams.get('status');
          let query  = `SELECT r.*, e.title as event_title FROM registrations r JOIN events e ON e.id = r.event_id WHERE 1=1`;
          const params = [];
          if (eventFilter)  { query += ` AND r.event_id = ?`;        params.push(eventFilter); }
          if (statusFilter) { query += ` AND r.paiement_status = ?`; params.push(statusFilter); }
          query += ` ORDER BY e.date_start ASC, r.created_at ASC`;
          const stmt = env.DB.prepare(query);
          const { results } = await (params.length ? stmt.bind(...params) : stmt).all();
          return json(results);
        }

        // GET /api/registrations/:id [admin]
        if (method === 'GET' && resId && !subRes) {
          await requireAdmin();
          const reg = await env.DB.prepare(
            `SELECT r.*, e.title as event_title, e.price as event_price
             FROM registrations r JOIN events e ON e.id = r.event_id WHERE r.id = ?`
          ).bind(resId).first();
          if (!reg) return err('Inscription introuvable', 404);
          return json(reg);
        }

        // POST /api/registrations [public]
        if (method === 'POST' && !resId) {
          // Rate limiting : 10 inscriptions max par IP par minute
          const clientIp = request.headers.get('CF-Connecting-IP') || request.headers.get('X-Forwarded-For') || 'unknown';
          if (isRateLimited(clientIp, 10, 60_000)) {
            return err('Trop de requêtes. Veuillez patienter avant de réessayer.', 429);
          }

          const body = await request.json();
          const result = await createRegistrationRow(env, body);
          if (!result.ok) {
            return json({
              error: 'Une inscription existe déjà pour cet email à cet événement.',
              code: 'duplicate_registration',
              existing_id: result.existing_id,
              paiement_status: result.paiement_status,
              montant: result.montant,
            }, 409);
          }

          const { id, ev, paiementStatus, normalizedEmail, bodyUsed, cancelToken } = result;
          const regData = {
            nom: bodyUsed.nom, prenom: bodyUsed.prenom, email: normalizedEmail,
            telephone: bodyUsed.telephone, date_naissance: bodyUsed.date_naissance,
            categorie: bodyUsed.categorie ?? null, niveau: bodyUsed.niveau ?? null,
            licence_ffk: bodyUsed.licence_ffk ?? null, message: bodyUsed.message ?? null,
            is_mineur: bodyUsed.is_mineur ? 1 : 0,
            parent_nom: bodyUsed.parent_nom ?? null, parent_prenom: bodyUsed.parent_prenom ?? null, parent_tel: bodyUsed.parent_tel ?? null,
            paiement_status: paiementStatus,
          };
          const emailResults = await sendConfirmationEmails(env, { reg: regData, ev, cancelToken });
          return json({
            id,
            event_id: bodyUsed.event_id,
            paiement_status: paiementStatus,
            montant: ev.price,
            emails: emailResults,
          }, 201);
        }


        // PUT /api/registrations/:id/status [admin]
        if (method === 'PUT' && resId && subRes === 'status') {
          await requireAdmin();
          const body = await request.json();
          const validStatuses = ['en_attente', 'paye', 'gratuit', 'annule'];
          if (!validStatuses.includes(body.paiement_status)) {
            return err(`Statut invalide. Valeurs : ${validStatuses.join(', ')}`);
          }
          const registration = await env.DB.prepare(
            `SELECT event_id FROM registrations WHERE id = ?`
          ).bind(resId).first();
          if (!registration) return err('Inscription introuvable', 404);
          const info = await env.DB.prepare(`
            UPDATE registrations SET paiement_status = ?, helloasso_ref = COALESCE(?, helloasso_ref) WHERE id = ?
          `).bind(body.paiement_status, body.helloasso_ref ?? null, resId).run();
          if (info.changes === 0) return err('Inscription introuvable', 404);
          await syncEventAvailability(env.DB, registration.event_id);
          if (body.paiement_status === 'annule') await notifyNextWaitlistEntry(env, registration.event_id);
          return json({ id: resId, paiement_status: body.paiement_status });
        }

        // DELETE /api/registrations/:id [admin]
        // ── Supprime l'inscription ET restitue une place sur l'événement ──
        if (method === 'DELETE' && resId) {
          await requireAdmin();

          const reg = await env.DB.prepare(
            `SELECT event_id, paiement_status FROM registrations WHERE id = ?`
          ).bind(resId).first();
          if (!reg) return err('Inscription introuvable', 404);

          const info = await env.DB.prepare(
            `DELETE FROM registrations WHERE id = ?`
          ).bind(resId).run();
          if (info.changes === 0) return err('Inscription introuvable', 404);

          await syncEventAvailability(env.DB, reg.event_id);
          await notifyNextWaitlistEntry(env, reg.event_id);

          return json({ deleted: Number(resId), event_id: reg.event_id });
        }
      }

      // ══════════════════════════════════════════════════════════
      //  LISTE D'ATTENTE
      // ══════════════════════════════════════════════════════════
      if (resource === 'waitlist') {

        // POST /api/waitlist [public] — rejoindre la liste d'attente d'un
        // événement complet ou fermé. Body : { event_id, nom, prenom, email, telephone }
        if (method === 'POST' && !resId) {
          const clientIp = request.headers.get('CF-Connecting-IP') || request.headers.get('X-Forwarded-For') || 'unknown';
          if (isRateLimited(`waitlist:${clientIp}`, 10, 60_000)) {
            return err('Trop de requêtes. Veuillez patienter avant de réessayer.', 429);
          }
          const body = await request.json();
          const required = ['event_id', 'nom', 'prenom', 'email'];
          for (const f of required) {
            if (!body[f]) return err(`Champ requis manquant : ${f}`);
          }
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) return err('Email invalide');

          const rawEvent = await env.DB.prepare(`SELECT * FROM events WHERE id = ?`).bind(body.event_id).first();
          if (!rawEvent) return err('Événement introuvable', 404);
          const ev = await hydrateEvent(env.DB, rawEvent);
          if (ev.spots_left > 0) return err("Cet événement a encore des places disponibles : inscrivez-vous directement.", 409);

          const normalizedEmail = String(body.email).toLowerCase().trim();
          try {
            const info = await env.DB.prepare(`
              INSERT INTO waitlist (event_id, nom, prenom, email, telephone)
              VALUES (?, ?, ?, ?, ?)
            `).bind(body.event_id, body.nom, body.prenom, normalizedEmail, body.telephone ?? null).run();
            return json({ id: info.meta.last_row_id, event_id: body.event_id }, 201);
          } catch (insertError) {
            if (isUniqueConstraintError(insertError, 'idx_waitlist_unique_email_event')) {
              return json({ error: 'Vous êtes déjà sur la liste d\'attente pour cet événement.', code: 'duplicate_waitlist' }, 409);
            }
            throw insertError;
          }
        }

        // GET /api/waitlist?event_id=... [admin]
        if (method === 'GET' && !resId) {
          await requireAdmin();
          const eventFilter = url.searchParams.get('event_id');
          let query = `SELECT w.*, e.title AS event_title FROM waitlist w JOIN events e ON e.id = w.event_id WHERE 1=1`;
          const params = [];
          if (eventFilter) { query += ` AND w.event_id = ?`; params.push(eventFilter); }
          query += ` ORDER BY w.event_id, w.created_at ASC`;
          const stmt = env.DB.prepare(query);
          const { results } = await (params.length ? stmt.bind(...params) : stmt).all();
          return json(results);
        }

        // DELETE /api/waitlist/:id [admin]
        if (method === 'DELETE' && resId) {
          await requireAdmin();
          const info = await env.DB.prepare(`DELETE FROM waitlist WHERE id = ?`).bind(resId).run();
          if (info.changes === 0) return err('Entrée de liste d\'attente introuvable', 404);
          return json({ deleted: Number(resId) });
        }
      }

      // ══════════════════════════════════════════════════════════
      //  AUTO-ANNULATION PUBLIQUE PAR LIEN SIGNÉ (non-adhérents)
      // ══════════════════════════════════════════════════════════
      // GET  /api/registrations/cancel/:token → aperçu (nom, événement, éligibilité)
      // POST /api/registrations/cancel/:token → confirme l'annulation
      // Réutilise canCancelByToken (même règle que canMemberCancelRegistration :
      // pas d'auto-annulation d'un paiement confirmé ni d'un événement passé).
      {
        const cancelTokenMatch = path.match(/^\/api\/registrations\/cancel\/([a-zA-Z0-9-]+)$/);
        if (cancelTokenMatch) {
          const cancelToken = cancelTokenMatch[1];
          const row = await env.DB.prepare(`
            SELECT r.id, r.event_id, r.nom, r.prenom, r.email, r.paiement_status, r.cancel_token,
                   e.title, e.date_start, e.lieu
            FROM registrations r JOIN events e ON e.id = r.event_id
            WHERE r.cancel_token = ?
          `).bind(cancelToken).first();

          if (method === 'GET') {
            if (!row) return err('Lien invalide ou déjà utilisé', 404);
            const eligibility = canCancelByToken(
              { paiement_status: row.paiement_status },
              { date_start: row.date_start },
            );
            return json({
              nom: row.nom, prenom: row.prenom, event_title: row.title,
              date_start: row.date_start, lieu: row.lieu,
              paiement_status: row.paiement_status,
              can_cancel: eligibility.ok, reason: eligibility.reason ?? null,
            });
          }

          if (method === 'POST') {
            if (!row) return err('Lien invalide ou déjà utilisé', 404);
            const eligibility = canCancelByToken(
              { paiement_status: row.paiement_status },
              { date_start: row.date_start },
            );
            if (!eligibility.ok) {
              const messages = {
                already_cancelled: 'Cette inscription est déjà annulée.',
                paid_requires_refund: "Cette inscription a déjà été payée : contactez le club pour organiser un remboursement avant de l'annuler.",
                event_passed: 'Impossible d\'annuler une inscription à un événement déjà passé.',
                not_found: 'Inscription introuvable',
              };
              return err(messages[eligibility.reason] || 'Annulation impossible.', 409);
            }
            // Jeton à usage unique : on l'invalide en même temps que l'annulation
            // pour qu'un lien déjà utilisé ne puisse pas resservir.
            await env.DB.prepare(
              `UPDATE registrations SET paiement_status = 'annule', cancel_token = NULL WHERE id = ?`
            ).bind(row.id).run();
            await syncEventAvailability(env.DB, row.event_id);
            await notifyNextWaitlistEntry(env, row.event_id);
            try {
              await sendMemberCancellationEmail(env, { reg: row, ev: row });
            } catch (e) {
              console.error('[registrations/cancel] notification bureau échouée', e?.message || e);
            }
            return json({ ok: true });
          }
        }
      }

      // ══════════════════════════════════════════════════════════
      //  AVIS PUBLICS SUR LES ÉVÉNEMENTS
      // ══════════════════════════════════════════════════════════
      if (resource === 'reviews') {

        // POST /api/reviews [public] — soumission d'un avis, non publié tant
        // que l'admin ne l'a pas validé (cf. PUT .../publish ci-dessous).
        if (method === 'POST' && !resId) {
          const clientIp = request.headers.get('CF-Connecting-IP') || request.headers.get('X-Forwarded-For') || 'unknown';
          if (isRateLimited(`reviews:${clientIp}`, 5, 60_000)) {
            return err('Trop de requêtes. Veuillez patienter avant de réessayer.', 429);
          }
          const body = await request.json();
          if (!body.event_id || !body.nom || !body.note) {
            return err('Champs requis manquants : event_id, nom, note');
          }
          const note = Number(body.note);
          if (!Number.isInteger(note) || note < 1 || note > 5) return err('note doit être un entier entre 1 et 5');
          const ev = await env.DB.prepare(`SELECT id FROM events WHERE id = ?`).bind(body.event_id).first();
          if (!ev) return err('Événement introuvable', 404);

          const info = await env.DB.prepare(`
            INSERT INTO event_reviews (event_id, nom, email, note, commentaire)
            VALUES (?, ?, ?, ?, ?)
          `).bind(body.event_id, body.nom, body.email ?? null, note, body.commentaire ?? null).run();
          return json({ id: info.meta.last_row_id, statut: 'en_attente_moderation' }, 201);
        }

        // GET /api/reviews?event_id=... [public] — avis publiés uniquement
        if (method === 'GET' && !resId) {
          const eventFilter = url.searchParams.get('event_id');
          let query = `SELECT id, event_id, nom, note, commentaire, created_at FROM event_reviews WHERE publie = 1`;
          const params = [];
          if (eventFilter) { query += ` AND event_id = ?`; params.push(eventFilter); }
          query += ` ORDER BY created_at DESC LIMIT 100`;
          const stmt = env.DB.prepare(query);
          const { results } = await (params.length ? stmt.bind(...params) : stmt).all();
          return json(results);
        }

        // GET /api/reviews/admin [admin] — tous les avis, y compris non publiés
        if (method === 'GET' && resId === 'admin') {
          await requireAdmin();
          const { results } = await env.DB.prepare(
            `SELECT r.*, e.title AS event_title FROM event_reviews r JOIN events e ON e.id = r.event_id ORDER BY r.created_at DESC`
          ).all();
          return json(results);
        }

        // PUT /api/reviews/:id/publish [admin] — bascule publié/non publié
        if (method === 'PUT' && resId && subRes === 'publish') {
          await requireAdmin();
          const body = await request.json();
          const info = await env.DB.prepare(
            `UPDATE event_reviews SET publie = ? WHERE id = ?`
          ).bind(body.publie ? 1 : 0, resId).run();
          if (info.changes === 0) return err('Avis introuvable', 404);
          return json({ id: Number(resId), publie: !!body.publie });
        }

        // DELETE /api/reviews/:id [admin]
        if (method === 'DELETE' && resId) {
          await requireAdmin();
          const info = await env.DB.prepare(`DELETE FROM event_reviews WHERE id = ?`).bind(resId).run();
          if (info.changes === 0) return err('Avis introuvable', 404);
          return json({ deleted: Number(resId) });
        }
      }

      // ══════════════════════════════════════════════════════════
      //  CHECKOUT HELLOASSO
      // ══════════════════════════════════════════════════════════
      //
      // L'inscription est créée ici (statut "en_attente"), AVANT la redirection
      // vers HelloAsso — et non plus après le retour, sur la seule foi d'un
      // paramètre d'URL construit côté navigateur (faille corrigée : rien
      // n'empêchait auparavant de fabriquer directement l'URL de retour pour
      // réserver une place sans jamais payer). Le retour de paiement passe par
      // /api/checkout/callback (GET, ci-dessous), qui interroge l'API HelloAsso
      // server-to-server avant de valider quoi que ce soit.
      if (resource === 'checkout' && method === 'POST') {
        // Même limite que /api/registrations : la création d'inscription a lieu
        // ici désormais, donc le rate limit doit s'appliquer ici aussi.
        const clientIp = request.headers.get('CF-Connecting-IP') || request.headers.get('X-Forwarded-For') || 'unknown';
        if (isRateLimited(clientIp, 10, 60_000)) {
          return err('Trop de requêtes. Veuillez patienter avant de réessayer.', 429);
        }

        const body = await request.json();
        if (!body.event_id || !body.nom || !body.prenom || !body.email) {
          return err('Champs requis : event_id, nom, prenom, email');
        }
        const rawEvent = await env.DB.prepare('SELECT * FROM events WHERE id = ?').bind(body.event_id).first();
        const evCheck = rawEvent ? await hydrateEvent(env.DB, rawEvent) : null;
        if (!evCheck)                     return err('Evenement introuvable', 404);
        if (evCheck.price === 0)          return err('Evenement gratuit, pas de checkout', 400);

        const result = await createRegistrationRow(env, body);
        if (!result.ok) {
          return json({
            error: 'Une inscription existe déjà pour cet email à cet événement.',
            code: 'duplicate_registration',
            existing_id: result.existing_id,
            paiement_status: result.paiement_status,
            montant: result.montant,
          }, 409);
        }

        const { id: registrationId, ev } = result;
        const origin    = url.origin;
        const returnUrl = `${origin}/api/checkout/callback?registration_id=${registrationId}&result=success`;
        const errorUrl  = `${origin}/api/checkout/callback?registration_id=${registrationId}&result=error`;

        try {
          const { redirectUrl, checkoutIntentId } = await createHelloAssoCheckout(env, {
            eventTitle: ev.title,
            amount:     ev.price,
            email: body.email, prenom: body.prenom, nom: body.nom,
            returnUrl, errorUrl,
          });
          await env.DB.prepare(`UPDATE registrations SET helloasso_ref = ? WHERE id = ?`)
            .bind(checkoutIntentId, registrationId).run();
          return json({ redirectUrl, registration_id: registrationId });
        } catch (checkoutError) {
          // Le checkout HelloAsso n'a pas pu être créé : on annule tout de suite
          // l'inscription "en_attente" pour ne pas bloquer la place pour rien.
          await env.DB.prepare(`UPDATE registrations SET paiement_status = 'annule' WHERE id = ?`)
            .bind(registrationId).run();
          await syncEventAvailability(env.DB, body.event_id);
          throw checkoutError;
        }
      }

      // GET /api/checkout/callback — retour HelloAsso (succès ou échec/annulation).
      // Jamais appelé directement par le front : c'est l'URL vers laquelle
      // HelloAsso redirige le navigateur après paiement.
      if (resource === 'checkout' && resId === 'callback' && method === 'GET') {
        const registrationId = url.searchParams.get('registration_id');
        const outcome        = url.searchParams.get('result');
        const origin          = url.origin;
        const redirectTo = (params) => Response.redirect(`${origin}/?${new URLSearchParams(params).toString()}`, 302);

        if (!registrationId) return redirectTo({ checkout: 'error' });

        const reg = await env.DB.prepare(`SELECT * FROM registrations WHERE id = ?`).bind(registrationId).first();
        if (!reg) return redirectTo({ checkout: 'error' });

        // Retour "annulé" ou "échoué" côté HelloAsso : on libère la place tout de
        // suite plutôt que d'attendre le cron de purge des paniers abandonnés.
        if (outcome !== 'success') {
          if (reg.paiement_status === 'en_attente') {
            await env.DB.prepare(`UPDATE registrations SET paiement_status = 'annule' WHERE id = ?`).bind(registrationId).run();
            await syncEventAvailability(env.DB, reg.event_id);
          }
          return redirectTo({ checkout: 'error', event_id: reg.event_id, registration_id: reg.id, reason: 'cancelled' });
        }

        // Déjà confirmée (ex. rechargement du callback) : pas besoin de revérifier.
        if (reg.paiement_status === 'paye') {
          return redirectTo({ checkout: 'success', event_id: reg.event_id, registration_id: reg.id, paiement_status: 'paye' });
        }

        if (!reg.helloasso_ref) {
          return redirectTo({ checkout: 'error', event_id: reg.event_id, registration_id: reg.id, reason: 'missing_reference' });
        }

        try {
          const intent = await getHelloAssoCheckoutIntent(env, reg.helloasso_ref);
          const paymentState = buildHelloAssoPaymentState(intent, reg.montant);
          if (paymentState.paid) {
            await env.DB.prepare(`UPDATE registrations SET paiement_status = 'paye' WHERE id = ?`).bind(registrationId).run();
            const rawEvent = await env.DB.prepare('SELECT * FROM events WHERE id = ?').bind(reg.event_id).first();
            const ev = rawEvent ? await hydrateEvent(env.DB, rawEvent) : null;
            let emailSent = false;
            if (ev) {
              const emailResults = await sendConfirmationEmails(env, { reg: { ...reg, paiement_status: 'paye' }, ev, cancelToken: reg.cancel_token });
              emailSent = !!emailResults?.participant?.ok;
            }
            return redirectTo({
              checkout: 'success', event_id: reg.event_id, registration_id: reg.id,
              paiement_status: 'paye', email_sent: emailSent ? '1' : '0',
            });
          }
          // Vérifié auprès de HelloAsso mais pas (encore) payé : on n'annule pas
          // immédiatement (latence possible côté HelloAsso) — le cron de purge des
          // paniers abandonnés s'en chargera si ça ne se confirme jamais.
          return redirectTo({ checkout: 'error', event_id: reg.event_id, registration_id: reg.id, reason: 'not_paid' });
        } catch (verifyError) {
          console.error('[checkout/callback] vérification HelloAsso échouée', verifyError);
          return redirectTo({ checkout: 'error', event_id: reg.event_id, registration_id: reg.id, reason: 'verification_error' });
        }
      }

      // ── GET /api/member/registrations — espace membre ────────────────────
      // Vérifie le jeton signé émis par gestion (même SESSION_SECRET, même
      // format createSessionToken/parseSessionToken — les deux Workers
      // partagent déjà exactement le même schéma HMAC) et renvoie les
      // inscriptions de l'adhérent, retrouvées par email. Lecture seule,
      // token en en-tête Authorization (jamais de cookie ici : ce Worker n'a
      // pas à connaître le cookie de session de gestion).
      if (method === 'GET' && path === '/api/member/registrations') {
        const authHeader = request.headers.get('Authorization') || '';
        const token = authHeader.replace(/^Bearer\s+/i, '').trim();
        if (!token) return err('Non autorisé', 401);

        let session;
        try {
          session = await parseSessionToken(token, env);
        } catch (e) {
          console.error('[member/registrations] SESSION_SECRET absent ou invalide côté calendrier', e);
          return err('Service momentanément indisponible', 503);
        }
        if (!session || session.kind !== 'member' || !session.email || Number(session.expiresAt) < Date.now()) {
          return err('Session invalide ou expirée', 401);
        }

        const email = String(session.email).trim().toLowerCase();
        // Seules les inscriptions dont le paiement est validé (payé ou
        // gratuit) apparaissent dans l'espace membre : une inscription en
        // attente de paiement n'est pas encore un engagement définitif du
        // point de vue de l'adhérent, et une inscription annulée ne doit pas
        // s'afficher comme si elle était toujours active.
        const { results } = await env.DB.prepare(`
          SELECT r.id, r.event_id, r.paiement_status, r.created_at,
                 e.title, e.sub, e.type, e.date_start, e.date_end, e.time_start, e.lieu, e.price
          FROM registrations r
          JOIN events e ON e.id = r.event_id
          WHERE LOWER(TRIM(r.email)) = ?
            AND r.paiement_status IN ('paye', 'gratuit')
          ORDER BY e.date_start DESC
        `).bind(email).all();

        return new Response(JSON.stringify({ data: results || [], error: null }), {
          headers: securityHeaders({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }),
        });
      }

      // ── DELETE /api/member/registrations/:id — espace membre ─────────────
      // Auto-annulation par l'adhérent·e, sur le même principe d'auth que la
      // route GET ci-dessus (jeton signé, header Authorization uniquement).
      // Double vérification de propriété : l'inscription doit appartenir à
      // l'email du jeton, pas juste exister — sans ça n'importe quel
      // adhérent connecté pourrait annuler l'inscription de quelqu'un
      // d'autre en devinant un id. L'éligibilité (statut, date passée) est
      // déléguée à canMemberCancelRegistration, gardée pure pour les tests.
      const memberRegCancelMatch = path.match(/^\/api\/member\/registrations\/(\d+)$/);
      if (method === 'DELETE' && memberRegCancelMatch) {
        const registrationId = Number(memberRegCancelMatch[1]);
        const authHeader = request.headers.get('Authorization') || '';
        const token = authHeader.replace(/^Bearer\s+/i, '').trim();
        if (!token) return err('Non autorisé', 401);

        let session;
        try {
          session = await parseSessionToken(token, env);
        } catch (e) {
          console.error('[member/registrations:cancel] SESSION_SECRET absent ou invalide côté calendrier', e);
          return err('Service momentanément indisponible', 503);
        }
        if (!session || session.kind !== 'member' || !session.email || Number(session.expiresAt) < Date.now()) {
          return err('Session invalide ou expirée', 401);
        }

        const email = String(session.email).trim().toLowerCase();
        const row = await env.DB.prepare(`
          SELECT r.id, r.event_id, r.email, r.nom, r.prenom, r.paiement_status,
                 e.title, e.date_start, e.lieu
          FROM registrations r
          JOIN events e ON e.id = r.event_id
          WHERE r.id = ?
        `).bind(registrationId).first();

        if (!row || String(row.email).trim().toLowerCase() !== email) {
          // Message identique, inscription inexistante ou appartenant à
          // quelqu'un d'autre : on ne révèle jamais laquelle des deux.
          return err('Inscription introuvable', 404);
        }

        const eligibility = canMemberCancelRegistration(
          { paiement_status: row.paiement_status },
          { date_start: row.date_start },
        );
        if (!eligibility.ok) {
          const messages = {
            already_cancelled: 'Cette inscription est déjà annulée.',
            paid_requires_refund: "Cette inscription a déjà été payée : contactez le club pour organiser un remboursement avant de l'annuler.",
            event_passed: 'Impossible d\'annuler une inscription à un événement déjà passé.',
            not_found: 'Inscription introuvable',
          };
          return err(messages[eligibility.reason] || 'Annulation impossible.', 409);
        }

        const info = await env.DB.prepare(
          `UPDATE registrations SET paiement_status = 'annule' WHERE id = ?`
        ).bind(registrationId).run();
        if (info.changes === 0) return err('Inscription introuvable', 404);
        await syncEventAvailability(env.DB, row.event_id);
        await notifyNextWaitlistEntry(env, row.event_id);

        // Best-effort : le bureau est notifié pour suivre les désistements,
        // mais un échec d'envoi ne doit jamais faire échouer l'annulation
        // elle-même côté adhérent (même logique que les autres emails ici).
        try {
          await sendMemberCancellationEmail(env, { reg: row, ev: row });
        } catch (e) {
          console.error('[member/registrations:cancel] email de notification échoué', e);
        }

        return new Response(JSON.stringify({ data: { cancelled: true, id: registrationId, event_id: row.event_id }, error: null }), {
          headers: securityHeaders({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }),
        });
      }

      return err('Route introuvable', 404);

    } catch (e) {
      if (e instanceof ApiError) return err(e.message, e.status);
      console.error(e);
      return err('Erreur serveur interne', 500);
    }
  },
};
